  "prompt": "prompts/physics_committee_terra_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B018",
      "proposed_laureates": [
        "Charles L. Bennett",
        "Lyman A. Page"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP made the early universe quantitatively accessible and established a remarkably precise cosmological framework from the microwave sky.",
        "attribution": "Bennett and Page are highly visible scientific leaders of the mission; Spergel is a compelling representative of its cosmological interpretation.",
        "maturity": "The measurements and their implications have been tested extensively over two decades, including by later surveys.",
        "uncertainties": [
          "Separating mission leadership from the indispensable wider collaboration requires careful expert review."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B056",
      "proposed_laureates": [
        "Sheperd S. Doeleman",
        "Heino Falcke"
      ],
      "assessment": {
        "nobel_worthiness": "Horizon-scale imaging transformed a formerly indirect prediction about black holes into a vivid and stringent observational achievement.",
        "attribution": "Doeleman and Falcke have unusually central roles in realizing and motivating the global interferometric enterprise.",
        "maturity": "The result has survived independent analysis, subsequent imaging, and comparison across black-hole targets.",
        "uncertainties": [
          "The discovery rests on a very large collaboration, making the necessarily limited individual attribution difficult."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Jean-Loup Puget",
        "George Efstathiou"
      ],
      "assessment": {
        "nobel_worthiness": "Planck supplied the definitive all-sky precision test of the standard cosmological picture and a rich legacy of constraints on fundamental physics.",
        "attribution": "Puget and Efstathiou represent major instrumental and scientific leadership, while Mandolesi also merits close consideration.",
        "maturity": "Its data products and conclusions have been repeatedly scrutinized and remain central to cosmology.",
        "uncertainties": [
          "There is substantial conceptual and personnel overlap with earlier CMB missions, so the distinct prize-worthy advance must be sharply defined."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation and the quantum account of primordial structure are among the most consequential ideas connecting fundamental theory with the observed universe.",
        "attribution": "Guth, Linde, and Mukhanov represent complementary essential steps: the inflationary idea, its workable realization, and the calculable origin of fluctuations.",
        "maturity": "Its broad predictions have received powerful support from the CMB and large-scale structure, though no unique microscopic realization is established.",
        "uncertainties": [
          "The inflationary mechanism is not uniquely selected by present observations.",
          "The precise division of credit among the many foundational contributors would need especially careful historical assessment."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Günter Wolf",
        "Paul Söding"
      ],
      "assessment": {
        "nobel_worthiness": "Three-jet events gave compelling experimental evidence for the gluon, a cornerstone of the now-confirmed theory of strong interactions.",
        "attribution": "Wolf and Söding are plausible representatives of the experimental work, with Sau Lan Wu also warranting examination.",
        "maturity": "The gluon is established beyond reasonable doubt through a vast subsequent body of particle-physics evidence.",
        "uncertainties": [
          "The original evidence arose from large experimental collaborations and attribution to a few individuals may be contested."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Daniel J. Eisenstein",
        "John A. Peacock"
      ],
      "assessment": {
        "nobel_worthiness": "Baryon acoustic oscillations furnished a robust standard ruler and a remarkably clean observational route to the history of cosmic expansion.",
        "attribution": "Eisenstein is central to the observational breakthrough, while Peacock and Cole represent key theoretical and survey contributions.",
        "maturity": "The signal has been reproduced in multiple galaxy surveys and is now a standard cosmological probe.",
        "uncertainties": [
          "The contribution is intertwined with the broader development of precision survey cosmology."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Francis Halzen",
        "Christian Spiering"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube opened neutrino astronomy at high energies and demonstrated an entirely new way of observing the violent universe.",
        "attribution": "Halzen and Spiering are strong representatives of the conception and realization of the observatory; Karle deserves parallel consideration.",
        "maturity": "The astrophysical neutrino flux and identified source associations make this a durable observational discovery.",
        "uncertainties": [
          "The relevant achievement is collective, and the optimal boundary between detector invention and discovery needs clarification."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten"
      ],
      "assessment": {
        "nobel_worthiness": "Gauge/gravity duality is an exceptionally fertile conceptual advance, reshaping quantum gravity, field theory, and strongly coupled many-body physics.",
        "attribution": "Maldacena made the decisive correspondence explicit, with Witten and Polyakov central to its formulation and foundations.",
        "maturity": "Its theoretical influence is profound and sustained, with applications across several fields.",
        "uncertainties": [
          "There is no direct empirical confirmation of the correspondence as a description of nature.",
          "Its physical domain of validity and the historical allocation of foundational credit remain matters for expert scrutiny."
        ]
      }
    }
  ]
}
